INSERT INTO `knowledge_chapter` (`id`, `course_id`, `parent_id`, `chapter_code`, `title`, `level`, `sort_order`, `description`, `summary`) VALUES
(74, 1, 0, '4', '第 4 章 方法', 1, 4, '本章介绍 Java 语言中方法的定义与组成、方法调用及其调用-返回过程、按值传递、方法重载、变量的作用域和模块化编程，并通过求 π 值、输出素数、十进制与十六进制相互转换三个示例演示用方法进行模块化编程，最后给出培养团队意识、树立责任感两个课程思政素材。', '本章主要介绍 Java 语言中方法的定义、方法的调用、方法重载、变量的作用域等内容。'),
(75, 1, 74, '4.1', '方法定义', 2, 1, 'Java 语言定义方法（method）的一般语法形式如下所示：', NULL),
(76, 1, 74, '4.2', '方法调用', 2, 2, '方法是一个定义好的功能模块，为了使用方法完成相应的功能，必须调用它。方法调用就是传递参数给方法，然后执行方法中的代码。', NULL),
(77, 1, 74, '4.3', '按值传递', 2, 3, '当调用一个方法时，需要提供与该方法参数列表中形参相匹配的实参：实参必须与方法签名中定义的形参在顺序上和数量上匹配，在类型上兼容。类型兼容是指实参的值不需要强制类型转换（可以隐式类型转换）就可以传递给形参。例如，形参是 double 类型，传递的实参既可以是 int 类型的值，也可以是 float 类型的值。', NULL),
(78, 1, 74, '4.4', '方法重载', 2, 4, '方法重载（method overloading）是指可以使用相同的方法名来定义不同的方法，只要这些方法的参数列表是不同。换一种说法，方法重载就是定义方法名相同的一些方法，而这些方法的方法签名不同。方法重载可以减轻程序员的命名负担，提升程序的易读性。', NULL),
(79, 1, 74, '4.5', '变量的作用域', 2, 5, '一个变量的作用域是指该变量在程序中能被引用的范围。一个变量在其作用域之外被引用，Java 编译器会报告编译错误。', NULL),
(80, 1, 74, '4.6', '模块化编程', 2, 6, '方法是模块化编程的重要构造，每个方法可以看成是一个模块。通过模块化，可以促进代码复用。', NULL),
(81, 1, 74, '4.7', '示例学习', 2, 7, NULL, NULL),
(82, 1, 81, '4.7.1', '求 π 值', 3, 1, NULL, NULL),
(83, 1, 81, '4.7.2', '输出素数', 3, 2, NULL, NULL),
(84, 1, 81, '4.7.3', '十进制与十六进制相互转换', 3, 3, NULL, NULL),
(85, 1, 74, '4.8', '课程思政', 2, 8, NULL, NULL),
(86, 1, 85, '4.8.1', '培养团队意识', 3, 1, NULL, NULL),
(87, 1, 85, '4.8.2', '树立责任感', 3, 2, NULL, NULL);
