INSERT INTO `knowledge_difficult_point` (`id`, `chapter_id`, `description`, `type`, `page`, `page_order`) VALUES
(36, 75, '方法签名只由方法名和参数列表构成，不包括返回值类型：把 min(int,int) 写成 min(double,double) 才是不同签名，只改返回值类型则是重复定义，编译报错。', 3, 138, 1),
(37, 76, 'void 方法的调用必须是一条独立语句，不能写成 int k = printStr(3, "a");；带返回值方法的调用才可以作为一个值参与表达式运算。', 1, 138, 1),
(38, 76, '方法调用与返回的时机：调用时控制转移到被调用方法，只有执行到 return 语句或方法结束的右括号才返还控制；分析方法题输出时要按调用栈先进后出的顺序排列各行输出。', 2, 139, 1),
(39, 77, '类型兼容是单向的：int 值可以传给 double 形参（隐式转换），double 值传给 int 形参则编译错误，如 m(2.3, 2.3) 调用 m(double, int) 不合法。', 1, 140, 1),
(40, 77, '按值传递下形参只是实参值的副本，方法内对形参的赋值（如 b=b+1、swap 交换 d1 与 d2）不会影响实参，因此 swap(a, b) 交换不了 a、b。', 1, 142, 1),
(41, 77, '实参顺序错位会编译错误：show(12, "Java") 正确，show("Java", 12) 非法；实参数量也必须与形参一致，不能多给也不能少给。', 1, 143, 1),
(42, 78, '重载解析优先考虑精确匹配，再考虑类型兼容匹配：sum(2, 3) 匹配 sum(int, int)，sum(2, 3.5) 只能匹配 sum(double, double)，这是分析题与编程题的高频考点。', 2, 144, 1),
(43, 78, '歧义调用：只有 sum(double, int) 与 sum(int, double) 时，调用 sum(2, 3) 两个候选都只需一次隐式转换，编译器无法判定哪个更准确，报编译错误。', 1, 145, 1),
(44, 78, '重载与返回值类型、形参名称均无关：sum(int num1, int num2) 与 sum(int num3, int num4) 被视为同一方法；只有参数数量、类型或顺序不同才构成重载。', 3, 145, 2),
(45, 79, '局部变量没有默认赋值，使用前必须声明并初始化：int sum; 未赋初值就参与 sum=i+j 之外的运算（如读取自身）会编译错误，形参则由实参赋初值。', 1, 146, 1),
(46, 79, '同名局部变量的两种情形辨析：可以在同一方法的两个非嵌套语句块中各声明一个 i（multi1），但不可以在方法体已声明 i 后再在其嵌套的 for 块中声明 i（multi2）。', 3, 146, 2),
(47, 79, 'main 中声明的局部变量 x 会屏蔽同名的类变量 x：分析题中 m = x + y 使用的是局部 x 与类变量 y，注意区分两者的取值与可见范围。', 1, 146, 3),
(48, 80, '信息隐藏的边界：用户只需知道方法名、参数列表和返回值即可调用，方法体是“黑盒子”；只要方法签名不变，修改方法实现不影响调用者程序。', 3, 149, 1),
(49, 80, '调用其他类的 static 方法要写成“类名.方法名(实参列表)”，如 GCDMethodDemo.getGCD(54, 126)；同一类中的 static 方法才可以直接相互调用。', 2, 149, 2),
(50, 84, 'decToHex 必须用 do-while 而不是 while：当 d 为 0 时也要执行一次取余与拼接，否则得不到十六进制字符串 "0"。', 1, 153, 1);
INSERT INTO `knowledge_exercise` (`id`, `chapter_id`, `question`, `answer`, `difficulty`, `knowledge_point`, `page`, `page_order`) VALUES
(212, 74, '1、 当创建的方法不需要返回任何值时，需要采用以下哪个关键字作为返回值类型？（ ）\n(A) int　(B) void　(C) public　(D) double', 'B', 1, '方法定义', 157, 1),
(213, 74, '2、 方法签名的构成包括？（ ）\n(A) 方法名称　(B) 方法名称和参数列表\n(C) 返回类型、方法名和参数列表　(D) 参数列表', 'B', 1, '方法定义', 157, 2),
(214, 74, '3、 方法内部定义的变量称为（ ）\n(A) 全局变量　(B) 方法变量　(C) 局部变量　(D) 块变量', 'C', 1, '变量的作用域', 157, 3),
(215, 74, '4、 方法具体的实现细节被封装在方法内，并对调用该方法的用户隐藏，这被称为（ ）。\n(A) 信息隐藏　(B) 简化方法　(C) 方法隐藏　(D) 方法封装', 'A', 1, '模块化编程', 157, 4),
(216, 74, '5、 给定一个方法：public static void m(double d, int i)，下列哪个选项是不合法调用（ ）。\n(A) m(2.3, 2)　(B) m(2, 2)　(C) m(2d, 2)　(D) m(2.3, 2.3)', 'D', 1, '按值传递', 157, 5),
(217, 74, '6、 已知方法的定义形式为：public void plus(int a, int b){}，下列选项中哪个是合法的重载方法？（ ）\n(A) public int plus(int a){}　(B) public int plus1(int m, int n){}\n(C) public void plus(int a, int b){}　(D) public int plus(int a, int b){}', 'A', 1, '方法重载', 157, 6),
(218, 74, '7、 下列代码，前者与后者是重载关系的是：（ ）\n(A) public void show(){}和 public void show(int num){}\n(B) public void show(){}和 public void print(int num){}\n(C) public void show(){}和 public int show(){}\n(D) public void show(int a){}和 public void show1(int b){}', 'A', 1, '方法重载', 157, 7),
(219, 74, '8、 下列代码的运行结果为：（ ）\n```java\npublic class Method {\n   public String show(String name){\n         String oneSelf=name+"今年 20 岁了";\n         return oneSelf;\n   }\n   public static void main(String[] args){\n         Method method=new Method();\n         System.out.println(mwthod.show(“小红”));\n   }\n}\n```\n(A) 没有任何输出　(B) 编译错误\n(C) 小红今年 20 岁了　(D) 小红', 'B', 1, '方法调用', 157, 8),
(220, 74, '9、 分析以下代码,调用 nPrint（\'O\'，5）的输出是什么？（ ）\n```java\nstatic void nPrint(String message, int n) {\n   while (n > 0) {\n   System.out.print(message);\n   n--;\n   }\n}\n```\n(A) OOOOOO　(B) OOOOO　(C) OOOO　(D) 无效调用', 'D', 1, '方法调用', 157, 9),
(221, 74, '10、 以下代码中缺失的部分应该是（ ）。\n```java\npublic class Test {\n   public static void main(String[] args) {\n      System.out.println(f(5));\n   }\n   public static int f(int number) {\n      __________\n   }\n}\n```\n(A) return "number";　(B) return number;\n(C) System.out.println("number");　(D) System.out.println(number);', 'B', 1, '方法定义', 158, 10),
(222, 74, '1、 方法头指定方法的修饰符、________________、________________和________________ 。', '返回值类型；方法名；参数列表', 1, '方法定义', 158, 11),
(223, 74, '2、 方法定义时参数列表声明了方法中参数的________________、________________和________________。', '类型；顺序；个数', 1, '方法定义', 158, 12),
(224, 74, '3、 方法签名由________________和________________一起构成。', '方法名；参数列表', 1, '方法定义', 158, 13),
(225, 74, '4、 对于带返回值方法的调用，方法调用可以被作为一个________________来处理。', '值', 1, '方法调用', 158, 14),
(226, 74, '5、 对于不存在返回值的方法调用，方法调用必须是________________。', '一条语句', 1, '方法调用', 158, 15),
(227, 74, '6、 在进行参数传递时实参与形参应该具有相同的________________、________________和________________。', '顺序；数量；类型', 1, '按值传递', 158, 16),
(228, 74, '7、 当一个方法被调用时，系统会在内存中为该方法创建一个________________，用于保存该方法的参数和变量。', '活动记录', 1, '方法调用', 158, 17),
(229, 74, '8、 定义的两个方法拥有相同的方法名，但是它们的方法参数列表不同时，称为________________。', '方法重载', 1, '方法重载', 158, 18),
(230, 74, '9、 在方法中声明的变量称作________________。', '局部变量', 1, '变量的作用域', 158, 19),
(231, 74, '10、 在一个方法的不同语句块中________________(可以/不可以)声明同名的局部变量，________________(可以/不可以)在嵌套块中或同一块中两次声明同一个局部变量。', '可以；不可以', 1, '变量的作用域', 158, 20),
(232, 74, '11、 通过模块化，可以促进________________。', '代码复用', 1, '模块化编程', 158, 21),
(233, 74, '12、 以下代码的空白处应填写________________。\n```java\npublic class Test {\n   public static void main(String[] args) {\n      System.out.print("The square is ");\n      printSquare(8);\n   }\n   public static _____ printSquare(int score) {\n         System.out.println(score*score);\n      }\n}\n```', 'void', 1, '方法定义', 158, 22),
(234, 74, '1、 给出定义方法的一般语法形式，并进行说明。', '一般语法形式：\n[修饰符] 返回值类型 方法名（参数列表）{\n      //方法体；\n      语句组\n      [return 返回值；]\n}\n方法由一个方法头和一个方法体构成，方法头是“[修饰符] 返回值类型 方法名（参数列表）”，方法体由一对花括号及其括起来的语句组构成。（1）修饰符：可选项，声明方法的访问范围、类型，可用 public、private、protected、static、final 等，本章主要用 public static 以便在 main 方法中直接调用；（2）返回值类型：声明返回值的数据类型，可以是基本数据类型也可以是引用数据类型，无返回值时为 void；（3）方法名：一个合法的标识符；（4）参数列表：由 0 个或多个“数据类型 变量名称”构成，声明参数的类型、顺序和个数，其中的变量是形参，方法名和参数列表构成方法签名；（5）return 语句：返回值类型不为 void 时必须有 return 语句返回相应类型的值。', 2, '方法定义', 158, 23),
(235, 74, '2、 简述 return 语句的作用？void 方法是否允许有 return 语句。', 'return 语句的作用是把返回值送回到调用处，并结束本方法的执行，使程序控制返还给调用方法；方法有返回值时必须使用 return 语句返回相应数据类型的值，一般形式为“return 返回值;”。void 方法允许有 return 语句：可以不用 return 语句，也可以采用“return ;”形式的 return 语句（不带返回值），常用于在方法体中提前结束方法。', 2, '方法定义', 158, 24),
(236, 74, '3、 简要说明方法的调用方式。', '根据方法是否存在返回值，方法调用有两种方式：（1）带返回值方法的调用，方法调用可以被作为一个值来处理，如 int k = min(5, 8)；（2）不存在返回值的方法调用（void 方法），方法调用必须是一条语句，如 System.out.println("方法调用")。带返回值方法的调用也可以单独作为一条语句、忽略其返回值。在同一个类中定义的 static 方法可以直接相互调用；使用其他类的 public static 方法时采用“类名.方法名(实参列表)”的形式。调用发生时程序控制转移到被调用方法，执行完 return 语句或到达方法结束的右括号时，控制返还调用方法。', 2, '方法调用', 159, 25),
(237, 74, '4、 简述什么是值传递？', '当调用一个带参数的方法时，将实参的值传递给形参的过程被称为按值传递（pass-by-value）。传递的是实参的值而不是变量本身，实参与形参位于各自的活动记录中。当实参的值是基本数据类型时，形参的改变与实参没有关系；实参可以是类型兼容的字面值，也可以是类型兼容的变量，其实参值须与形参在顺序和数量上匹配、在类型上兼容。', 2, '按值传递', 159, 26),
(238, 74, '5、 把实参 a 传递给形参 b，实际传递的是什么？实参是否可以和形参同名？', '实际传递的是实参 a 的值（副本），该值按位置赋给形参 b，b 在被调用方法的活动记录中拥有自己的存储单元，对 b 的修改不会改变 a。实参可以和形参同名：它们是相互独立的不同变量，例如程序清单 4-2 中方法 main 的变量 i 与方法 decrease 的形参 i 同名，调用 decrease(i) 后形参 i 变为 4，而 main 中的 i 仍为 5。', 2, '按值传递', 159, 27),
(239, 74, '6、 简述什么是方法重载。是否可以在一个类中定义方法名、参数列表相同，但仅有返回值类型不同的方法？', '方法重载（method overloading）是指使用相同的方法名来定义不同的方法，只要这些方法的参数列表不同；换一种说法，就是定义方法名相同的一些方法，而这些方法的方法签名不同，它可以减轻命名负担、提升程序易读性。不可以：方法签名只由方法名和参数列表构成，重载方法的区分与返回值类型无关，方法名和参数列表相同而仅返回值类型不同的两个方法签名完全相同，属于重复定义，会产生编译错误。', 2, '方法重载', 159, 28),
(240, 74, '7、 在一个类中定义了两个重载方法：\n(A) public static void method(double x, double y)\n(B) public static void method(int x, double y)\n假如有下面一些方法调用，这些方法调用是否正确，匹配哪个方法？\n(1) method(2.0, 3); (2) method(2, 3); (3) method(2.0, 3.0); (4) method(2, 3.0);', '编译器优先考虑精确匹配，然后考虑类型兼容匹配。（1）method(2.0, 3)：调用正确，无精确匹配，按类型兼容匹配 B（第二个实参 int 值 3 隐式转换为 double）；（2）method(2, 3)：调用正确，匹配 B（B 只需转换第二个实参，比两个实参都要转换的 A 更具体）；（3）method(2.0, 3.0)：调用正确，精确匹配 A；（4）method(2, 3.0)：调用正确，精确匹配 B。', 2, '方法重载', 159, 29),
(241, 74, '8、 什么是局部变量，其作用域是什么？', '局部变量是在方法内部或语句块内部定义的变量。一个局部变量的作用域是从该变量声明的地方开始，直到包含该变量的语句块结束为止；局部变量在使用之前必须声明和初始化，没有默认赋值。方法的形参也是局部变量，其作用域是整个方法，初值由实参赋予。可以在一个方法的不同（非嵌套）语句块中声明同名的局部变量，但不能在嵌套块中或同一块中两次声明同一个局部变量，否则产生编译错误。', 2, '变量的作用域', 159, 30),
(242, 74, '1、 给出下面程序的输出结果。\n```java\npublic class TestAnalyze1 {\n      public static void main(String[] agrs) {\n            int sc=5;\n            System.out.print("结果为："+factorial(sc));\n       }\n      public static int factorial(int a){\n            int sum=1;\n             for(int i=1;i<=a;i++) {\n                sum=sum*i;\n               }\n            return sum;\n      }}\n```', '结果为：120\nfactorial(5) 用 for 循环求 1*2*3*4*5 = 120 并作为 int 值返回；main 用 System.out.print 输出，行末不换行。', 2, '方法调用', 159, 31),
(243, 74, '2、 给出下面程序的输出结果。\n```java\npublic class TestAnalyze2 {\n      public static void main(String[] args) {\n            int a= 10;\n            f(a);\n            System.out.println(a);\n      }\n      public static void f(int b){\n            b=b+1;\n      }}\n```', '10\n按值传递，调用 f(a) 时只把 a 的值 10 传给形参 b，方法内 b=b+1 使 b 变为 11，实参 a 不受影响，仍为 10。', 2, '按值传递', 159, 32),
(244, 74, '3、 给出下面程序的输出结果。\n```java\npublic class TestAnalyze3 {\n      public static void main(String[] args) {\n            int a = 3;\n            int b = 5;\n            swap(a, b);\n            System.out.println(a + ":" + b);\n      }\n      public static void swap(int i, int j){\n            int temp = i;\n            i = j;\n            j = temp;\n      }}\n```', '3:5\nswap(int i, int j) 交换的是两个形参（实参值的副本）所在活动记录中的值，main 中的 a、b 不发生变化，故输出仍为交换前的 3:5。', 2, '按值传递', 159, 33),
(245, 74, '4、 给出下面程序的输出结果。\n```java\npublic class TestAnalyze4 {\n      public static void main(String[] args) {\n           int a = 7;\n           int b = 8;\n           System.out.println(f(a,b));\n      }\n      public static int f(int i, int j){\n            int sum;\n            sum =i+j;\n            return sum;\n      }}\n```', '15\nf(7, 8) 中形参 i、j 分别获得实参 7、8，sum=i+j=15 被返回，方法调用作为 println 的一个值使用，输出 15。', 2, '方法调用', 160, 34),
(246, 74, '5、 给出下面程序的输出结果。\n```java\npublic class TestAnalyze5 {\n      static int x =3;\n      static int y = 4;\n      public static void main(String[] args) {\n            int x = 5;\n            int m ;\n            int n;\n            m = x + y;\n            n = f(m, y);\n            System.out.println("m= " + m+"; n="+n);\n       }\n       public static int f(int i, int j){\n            int n;\n            n =i+j;\n            return n;\n         }}\n```', 'm= 9; n=13\nmain 中的局部变量 x 声明后屏蔽了同名的类变量 x（值为 3），所以 m = x + y = 5 + 4 = 9；调用 f(9, 4) 返回 13 赋给 n，方法内的局部变量 n 与 main 中的 n 互不影响。注意输出中 "m= " 后有一个空格。', 2, '变量的作用域', 160, 35),
(247, 74, '6、 给出下面程序的输出结果。\n```java\npublic class TestAnalyze6 {\n      public static void main(String[] args){\n            char c1 = \'A\';\n            char c2 = \'a\';\n            System.out.println(f(c1, c2));\n      }\n      public static char f(char i, char j){\n            if (i>=j)\n                  return i;\n            else\n                  return j;\n      }}\n```', 'a\nchar 型实参 \'A\'(65)、\'a\'(97) 传给形参 i、j，条件 i>=j 即 65>=97 为 false，执行 else 分支返回 j，即字符 \'a\'，println 输出 a。', 2, '方法调用', 160, 36),
(248, 74, '7、 给出下面程序的输出结果。\n```java\npublic class TestAnalyze7 {\n      public static void main(String[] args){\n          System.out.println(show("晓明"));\n      }\n      public static String show(String name){\n          String imfo=name+"今年 7 岁了";\n          return imfo;\n      }}\n```', '晓明今年 7 岁了\nshow("晓明") 中 imfo = name + "今年 7 岁了"，String 与 String 连接得到新串并返回，输出该串（题面中的中文引号“晓明”按字符串字面值处理）。', 2, '方法调用', 161, 37),
(249, 74, '8、 给出下面程序的输出结果。\n```java\npublic class TestAnalyze8 {\n      public static void main(String[] args){\n         sum(15,8,4);\n      }\n      public static void sum(int a,int b,int c){\n         int sum=a+b+c;\n         System.out.println(“a+b+c=”+sum);\n      }}\n```', 'a+b+c=27\nsum(15, 8, 4) 是 void 方法调用，作为一条独立语句执行，方法内计算 sum=a+b+c=27 并输出，输出语句中的中文引号按字符串定界符处理。', 2, '方法调用', 161, 38),
(250, 74, '9、 给出下面程序的输出结果。\n```java\npublic class TestAnalyze9 {\n      public static void main(String[] args){\n         double price=120;\n         System.out.println(disCD(price));\n      }\n      public static double disCD(double a){\n         if(a<100){\n            a = a;\n         }\n         else{\n            a = a*0.9;\n         }\n         return a;\n      }}\n```', '108.0\ndisCD(120) 中形参 a 获得实参值 120.0，条件 a<100 不成立，执行 a = a*0.9 得 108.0 并返回；返回值类型为 double，println 输出 108.0。', 2, '方法调用', 161, 39),
(251, 74, '10、 给出下面程序的输出结果。\n```java\npublic class TestAnalyze10 {\n      public static void main(String[] args){\n         double c=1.2;\n         double a=6, b=5;\n         System.out.println("圆的面积是："+area(c));\n         System.out.println("矩形的面积是："+area(a,b));\n      }\n      public static double area(double a, double b){\n            return a*b;\n      }\n      public static double area(double a){\n            return a*a*3.14;\n      }}\n```', '圆的面积是：4.5216\n矩形的面积是：30.0\narea(c) 只有一个 double 实参，与 area(double a) 精确匹配，返回 1.2*1.2*3.14 = 4.5216；area(a, b) 与 area(double a, double b) 精确匹配，返回 6.0*5.0 = 30.0，double 值输出为 30.0。两个 area 方法名相同而参数列表不同，构成重载。', 2, '方法重载', 161, 40),
(252, 74, '1、 编写一个名为 printScopePrime(int m, int n)的方法，输出两个整数范围内[m, n]的素数，每行输出 10 个数。方法头为：\n```java\npublic static void printScopePrime(int m, int n)\n```\n测试程序要求输入 m，n 的值，然后输出结果。当 m>n 时，输出参数非法信息。例如：\n```\n请输入两个正整数 m、n(m<n):100 50\n参数不合法\n```\n又如，当 m=100，n=300 时，运行结果如下：\n```\n请输入两个正整数 m、n(m<n):100 300\n100 和 300 之间的素数有：\n101 103 107 109 113 127 131 137 139 149\n151 157 163 167 173 179 181 191 193 197\n199 211 223 227 229 233 239 241 251 257\n263 269 271 277 281 283 293\n```', '参考代码：\nimport java.util.Scanner;\npublic class Exercise4_1 {\n    public static void printScopePrime(int m, int n) {\n        if (m > n) { System.out.println("参数不合法"); return; }\n        System.out.println(m + " 和 " + n + " 之间的素数有：");\n        int count = 0;\n        for (int num = m; num <= n; num++) {\n            if (isPrime(num))\n                System.out.printf(++count % 10 == 0 ? "%d\\n" : "%d ", num);\n        }\n    }\n    public static boolean isPrime(int num) {\n        if (num < 2) return false;\n        for (int d = 2; d <= num / 2; d++) if (num % d == 0) return false;\n        return true;\n    }\n    public static void main(String[] args) {\n        Scanner input = new Scanner(System.in);\n        System.out.print("请输入两个正整数 m、n(m<n):");\n        int m = input.nextInt(), n = input.nextInt();\n        printScopePrime(m, n);\n    }\n}\n输入 100 300 时输出的素数与题面示例一致，每行 10 个。', 2, '输出素数', 162, 41),
(253, 74, '2、 编写一个名为 sumDigits 的方法，计算一个整数(num >9)的各位数字之和。方法头为：\n```java\npublic static int sumDigits(int num)\n```\n测试程序提示用户输入一个大于 9 的正整数。当 num 小于 9 时，输出提示信息：数值太小，请输入大于 9 的正整数。当 num 大于 9 时，调用 sumDigits 实现对输入的整数的各位数字求和并输出。\n运行结果示例如下：\n```\n请输入一个正整数>9：2345\n2345 的各位数字之和是：14\n```\n当输入不满足要求时，显示如下信息：\n```\n请输入一个正整数>9：8\n请输入大于 9 的正整数\n```', '参考代码：\nimport java.util.Scanner;\npublic class Exercise4_2 {\n    public static int sumDigits(int num) {\n        int sum = 0;\n        while (num > 0) { sum += num % 10; num /= 10; }\n        return sum;\n    }\n    public static void main(String[] args) {\n        Scanner input = new Scanner(System.in);\n        System.out.print("请输入一个正整数>9：");\n        int num = input.nextInt();\n        if (num < 9) System.out.println("请输入大于 9 的正整数");\n        else System.out.println(num + " 的各位数字之和是：" + sumDigits(num));\n    }\n}\n输入 2345 输出“2345 的各位数字之和是：14”，输入 8 输出提示信息。', 2, '方法定义', 162, 42),
(254, 74, '3、 编写一个求三个整数最大值的方法 max，该方法能够找出三个整数中的最大值并返回。在测试的 main 方法中，提示用户输入三个整数，调用方法后，得到三者的最大数并输出。', '参考代码：\nimport java.util.Scanner;\npublic class Exercise4_3 {\n    public static int max(int a, int b, int c) {\n        int m = a;\n        if (b > m) m = b;\n        if (c > m) m = c;\n        return m;\n    }\n    public static void main(String[] args) {\n        Scanner input = new Scanner(System.in);\n        System.out.print("请输入三个整数：");\n        int a = input.nextInt(), b = input.nextInt(), c = input.nextInt();\n        System.out.println("三个整数中的最大值是：" + max(a, b, c));\n    }\n}', 2, '方法定义', 162, 43),
(255, 74, '4、 编写一个方法 public static void printStars(int row, int col)，该方法打印 row 行高 col 列宽的由*构成的矩形，在测试的 main 方法中，提示用户输入 row、col，然后输出矩形。一个运行示例如下：\n```\n请输入两个正整数 m 行 n 列：3 5\n*****\n*****\n*****\n```', '参考代码：\nimport java.util.Scanner;\npublic class Exercise4_4 {\n    public static void printStars(int row, int col) {\n        for (int i = 0; i < row; i++) {\n            for (int j = 0; j < col; j++) System.out.print("*");\n            System.out.println();\n        }\n    }\n    public static void main(String[] args) {\n        Scanner input = new Scanner(System.in);\n        System.out.print("请输入两个正整数 m 行 n 列：");\n        int row = input.nextInt(), col = input.nextInt();\n        printStars(row, col);\n    }\n}\n输入 3 5 时输出 3 行 5 列的 * 矩形。', 2, '模块化编程', 162, 44),
(256, 74, '5、 要求按照从主方法传递的两个数字 n，m 分别代表行数和列数，在方法中输出对应的星形，并打印出来。', '参考代码：\nimport java.util.Scanner;\npublic class Exercise4_5 {\n    //从主方法传递 n、m，分别代表行数和列数\n    public static void printStars(int n, int m) {\n        for (int i = 1; i <= n; i++) {\n            for (int j = 1; j <= m; j++) System.out.print("* ");\n            System.out.println();\n        }\n    }\n    public static void main(String[] args) {\n        Scanner input = new Scanner(System.in);\n        System.out.print("请输入行数和列数 n、m：");\n        int n = input.nextInt(), m = input.nextInt();\n        printStars(n, m);\n    }\n}\n题面只给出“行数和列数”，此处按矩形星形实现；若需直角三角形，把内层循环条件改为 j <= i 且列数 m 作为最大列数即可。', 2, '方法调用', 162, 45),
(257, 74, '6、 将第 3 章编程题第 3 题改用方法实现，设计一个方法 solveEquation 求一元二次方程的解并打印出求解情况，其方法头如下：\n```java\npublic static void solveEquation(double a, double b, double c)\n```\n输出结果和第 3 章编程题第 3 题一样。', '参考代码：\nimport java.util.Scanner;\npublic class Exercise4_6 {\n    public static void solveEquation(double a, double b, double c) {\n        double d = b * b - 4 * a * c;\n        if (d < 0) System.out.println("该方程无实数解.");\n        else if (d == 0) System.out.printf("该方程只有一个实数解：%.6f.%n", -b / (2 * a));\n        else {\n            double root1 = (-b + Math.sqrt(d)) / (2 * a);\n            double root2 = (-b - Math.sqrt(d)) / (2 * a);\n            System.out.printf("该方程有两个实数解：%.6f, %.6f.%n", root1, root2);\n        }\n    }\n    public static void main(String[] args) {\n        Scanner input = new Scanner(System.in);\n        System.out.print("请输入方程(ax^2+bx+c)中的 a、b、c: ");\n        double a = input.nextDouble(), b = input.nextDouble(), c = input.nextDouble();\n        solveEquation(a, b, c);\n    }\n}\n输入 3 4 5 输出“该方程无实数解.”；输入 1.5 5.5 3.2 输出“该方程有两个实数解：-0.725282, -2.941385.”；输入 1 2 1 输出“该方程只有一个实数解：-1.000000.”，与第 3 章编程题第 3 题一致。', 2, '模块化编程', 162, 46),
(258, 74, '7、 编写一个方法 discount，根据商品总价，计算出对应的折扣并输出折后的总价。方法头为：\n```java\npublic static double discount(double total)\n```\n参数 total 表示商品总价，返回值是折扣价。\n折扣规则如下：商品总价 < = 100，不打折；100 < 商品总价 <= 500，9.5 折；500 < 商品总价 <= 1000，9.5 折。商品总价>=1000, 9 折。\n在测试的 main 方法中，提示用户商品总价，调用方法 discount()，输出商品总价和折扣后的价格。', '参考代码：\nimport java.util.Scanner;\npublic class Exercise4_7 {\n    public static double discount(double total) {\n        if (total <= 100) return total;              //总价<=100 不打折\n        else if (total <= 1000) return total * 0.95; //100<总价<=1000 按 9.5 折\n        else return total * 0.9;                     //总价>1000 按 9 折\n    }\n    public static void main(String[] args) {\n        Scanner input = new Scanner(System.in);\n        System.out.print("请输入商品总价：");\n        double total = input.nextDouble();\n        System.out.printf("商品总价：%.2f，折扣后的价格：%.2f%n", total, discount(total));\n    }\n}\n题面对 100<total<=500 与 500<total<=1000 均给出 9.5 折，故合并为一个区间；total 为 1000 时按 9.5 折处理。', 2, '方法定义', 163, 47),
(259, 74, '8、 将第 3 章编程题第 4 题改用方法实现，设计一个方法 judgeWin，以用户输入的数字作为参数，输出判定结果，方法头如下：\n```java\npublic static void judgeWin(int num)\n```\n输出结果和第 3 章编程题第 4 题一样。', '参考代码：\nimport java.util.Scanner;\npublic class Exercise4_8 {\n    public static void judgeWin(int num) {\n        int computer = (int) (Math.random() * 3) + 1;\n        String[] name = {"", "剪刀", "石头", "布"};\n        System.out.print("计算机选" + name[computer] + "，你选" + name[num] + "：");\n        if (num == computer) System.out.println("平局");\n        else if (num - computer == 1 || num - computer == -2) System.out.println("你赢了");\n        else System.out.println("你输了");\n    }\n    public static void main(String[] args) {\n        Scanner input = new Scanner(System.in);\n        System.out.print("剪刀-1, 石头-2, 布-3，请输入数字(1-3): ");\n        int num = input.nextInt();\n        judgeWin(num);\n    }\n}\n剪刀赢布、石头赢剪刀、布赢石头，与第 3 章编程题第 4 题输出格式相同。', 2, '模块化编程', 163, 48),
(260, 74, '9、 将第 3 章编程题第 5 题改用方法实现，设计一个方法 judgeTriangle，以用户输入的三条边为参数，返回布尔值，方法头如下：\n```java\npublic static boolean judgeTriangle(int a, int b, int c)\n```\n输出结果和第 3 章编程题第 5 题一样。', '参考代码：\nimport java.util.Scanner;\npublic class Exercise4_9 {\n    public static boolean judgeTriangle(int a, int b, int c) {\n        return a > 0 && b > 0 && c > 0 && a + b > c && a + c > b && b + c > a;\n    }\n    public static void main(String[] args) {\n        Scanner input = new Scanner(System.in);\n        System.out.print("请输入三角形的三条边：");\n        int a = input.nextInt(), b = input.nextInt(), c = input.nextInt();\n        if (a <= 0 || b <= 0 || c <= 0) System.out.println("三角形边长不能为负值");\n        else if (judgeTriangle(a, b, c)) System.out.println("这是一个合法的三角形");\n        else System.out.println("不满足两边之和大于第三边");\n    }\n}\n方法返回 boolean 值，可被直接用作 if 条件，与第 3 章编程题第 5 题输出一致。', 2, '方法定义', 163, 49),
(261, 74, '10、 将第 3 章编程题第 8 题改用方法实现，设计一个方法 getBMIState，以用户输入的身高、体重作为参数，返回字符串，方法头如下：\n```java\npublic static String getBMIState(double height, double weight)\n```\n输出结果和第 3 章编程题第 8 题一样。', '参考代码：\nimport java.util.Scanner;\npublic class Exercise4_10 {\n    public static String getBMIState(double height, double weight) {\n        double bmi = weight / (height * height);\n        if (bmi < 18.5) return "偏瘦";\n        else if (bmi < 25.0) return "正常";\n        else if (bmi < 30.0) return "超重";\n        else return "肥胖";\n    }\n    public static void main(String[] args) {\n        Scanner input = new Scanner(System.in);\n        System.out.print("请输入您的身高（米）：");\n        double height = input.nextDouble();\n        System.out.print("请输入您的体重（千克）：");\n        double weight = input.nextDouble();\n        System.out.printf("您的 BMI 是 %.2f,%s%n",\n            weight / (height * height), getBMIState(height, weight));\n    }\n}\n方法返回 String 类型的状态文本，输入 1.70、75 时输出“您的 BMI 是 25.95,超重”，与第 3 章编程题第 8 题一致。', 2, '方法定义', 163, 50),
(262, 74, '11、 将第 3 章编程题第 17 题改用方法实现，设计一个方法 sqroot，以需要求平方根的数作为参数，返回其平方根，方法头如下：\n```java\npublic static double sqroot(double d)\n```\n输出结果和第 3 章编程题第 17 题一样。', '参考代码：\nimport java.util.Scanner;\npublic class Exercise4_11 {\n    public static double sqroot(double d) {\n        double r = d;\n        while (Math.abs(r * r - d) >= 1e-05) r = (r + d / r) / 2;\n        return r;\n    }\n    public static void main(String[] args) {\n        Scanner input = new Scanner(System.in);\n        System.out.print("请输入一个正数(double 型)：");\n        double d = input.nextDouble();\n        System.out.printf("数 %.6f 的平方根是 %.6f%n", d, sqroot(d));\n    }\n}\n用两数之差小于 1e-05 作为 double 值相等的判据，输入 10.89 输出“数 10.890000 的平方根是 3.300000”。', 2, '方法定义', 163, 51),
(263, 74, '12、 将第 3 章编程题第 22 题改用方法实现，设计一个方法 printPyramid，以金字塔打印行数 layer 为参数，打印出金字塔，方法头如下：\n```java\npublic static void printPyramid(int layer)\n```\n输出结果和第 3 章编程题第 22 题一样。', '参考代码：\nimport java.util.Scanner;\npublic class Exercise4_12 {\n    public static void printPyramid(int layer) {\n        for (int i = 1; i <= layer; i++) {\n            for (int s = layer - i; s > 0; s--) System.out.print("  ");\n            for (int j = 1; j < i; j++) System.out.printf("%-4d", (int) Math.pow(2, j - 1));\n            for (int j = i; j >= 1; j--) System.out.printf("%-4d", (int) Math.pow(2, j - 1));\n            System.out.println();\n        }\n    }\n    public static void main(String[] args) {\n        Scanner input = new Scanner(System.in);\n        System.out.print("请输入金字塔打印行数 layer(1-7): ");\n        int layer = input.nextInt();\n        printPyramid(layer);\n    }\n}\n每行由 2 的幂先升后降排列（1 2 4 8 4 2 1），列数由 layer 决定，与第 3 章编程题第 22 题的图案形式一致。', 2, '模块化编程', 163, 52),
(264, 74, '13、 在一个 shape 类中，定义两个重载的方法 getArea，\n(1)求圆面积的方法：public static double getArea(double r)，r 表示半径\n(2) 求长方法面积的方法：public static double getArea(double w, double h)，w、h 分表表示长方形的宽和长\n在测试的 main 方法，指定 r 为 3.5，指定长方形的长为 12.5，宽为 9.8，调用重载的 getArea 方法计算圆和长方形的面积，并输出计算结果。', '参考代码：\npublic class Exercise4_13 {\n    public static double getArea(double r) { return Math.PI * r * r; }\n    public static double getArea(double w, double h) { return w * h; }\n    public static void main(String[] args) {\n        double r = 3.5;\n        double w = 9.8, h = 12.5;\n        System.out.printf("圆的面积是：%.4f%n", getArea(r));\n        System.out.printf("长方形的面积是：%.4f%n", getArea(w, h));\n    }\n}\n两个 getArea 方法名相同、参数个数不同，构成重载：getArea(r) 匹配圆面积方法，输出 38.4845；getArea(w, h) 匹配长方形面积方法，输出 122.5000。', 2, '方法重载', 163, 53),
(265, 74, '14、 编写一个温度转化工具类 TemperatureConvert，它有两个静态方法：\n```java\npublic static double ctoFahrenheit(double celsius) //摄氏温度转化为华氏温度\npublic static double ftoCelsius(double Fahrenheit) //华氏温度转化摄氏温度\n```\n转换公式如下：\n```\n华氏温度 = (9.0 / 5) * 摄氏温度 + 32\n摄氏温度 = (5.0 / 9) * (华氏温度 - 32)\n```\n编写测试程序 Excercise4_12，在其 main 方法中，输出摄氏温度从 10 开始，步长为 10，输出 10，20，…，50 对应的华氏温度，再输出华氏温度从 60 开始，步长为 10，输出 60，70，…. ，100 对应的摄氏温度。', '参考代码：\npublic class TemperatureConvert {\n    public static double ctoFahrenheit(double celsius) { return 9.0 / 5 * celsius + 32; }\n    public static double ftoCelsius(double Fahrenheit) { return 5.0 / 9 * (Fahrenheit - 32); }\n}\nclass Excercise4_12 {\n    public static void main(String[] args) {\n        for (double c = 10; c <= 50; c += 10)\n            System.out.printf("摄氏 %.1f 度 = 华氏 %.1f 度%n",\n                c, TemperatureConvert.ctoFahrenheit(c));\n        for (double f = 60; f <= 100; f += 10)\n            System.out.printf("华氏 %.1f 度 = 摄氏 %.1f 度%n",\n                f, TemperatureConvert.ftoCelsius(f));\n    }\n}\n测试程序以“类名.方法名(实参列表)”调用工具类的 static 方法，输出 10～50 度对应的华氏温度（50.0、68.0、…、122.0）和 60～100 华氏度对应的摄氏温度（15.6、21.1、…、37.8）。', 2, '模块化编程', 163, 54),
(266, 74, '15、 编写程序，统计一个字符串中指定字母出现的次数，其方法头是：\n```java\npublic static int countChar(String s, char c)\n```\n在测试的 main 方法中，提示用户输入字符串 s 和要查找的字符 c，然后，输出字符 c 在字符串中出现的次数。', '参考代码：\nimport java.util.Scanner;\npublic class Exercise4_15 {\n    public static int countChar(String s, char c) {\n        int count = 0;\n        for (int i = 0; i < s.length(); i++) if (s.charAt(i) == c) count++;\n        return count;\n    }\n    public static void main(String[] args) {\n        Scanner input = new Scanner(System.in);\n        System.out.print("请输入一个字符串 s：");\n        String s = input.next();\n        System.out.print("请输入要查找的字符 c：");\n        char c = input.next().charAt(0);\n        System.out.println("字符 " + c + " 在字符串中出现的次数是：" + countChar(s, c));\n    }\n}\n方法用 String 的 length 与 charAt 逐字符比较，如输入 banana、a 时输出 3。', 2, '方法定义', 164, 55),
(267, 74, '16、 回文数是指一个正整数从前往后、从后往前读数字都是一样的，比如，525，5225，都是回文数。请编写一个方法，判断一个正整数是否回文数，方法头：\n```java\npublic static boolean isPalinNumber(int num)\n```\n在测试的 main 方法中，提示用户输入一个正整数，并输出判别结果。', '参考代码：\nimport java.util.Scanner;\npublic class Exercise4_16 {\n    public static boolean isPalinNumber(int num) {\n        String s = num + "";\n        for (int i = 0, j = s.length() - 1; i < j; i++, j--)\n            if (s.charAt(i) != s.charAt(j)) return false;\n        return true;\n    }\n    public static void main(String[] args) {\n        Scanner input = new Scanner(System.in);\n        System.out.print("请输入一个正整数：");\n        int num = input.nextInt();\n        System.out.println(num + (isPalinNumber(num) ? " 是回文数" : " 不是回文数"));\n    }\n}\n把整数转为字符串后由两端向中间逐位比较，525、5225 输出“是回文数”，523 输出“不是回文数”。', 2, '方法定义', 164, 56),
(268, 74, '17、 回文素数是指一个正整数既是素数又是回文数，例如：727 是一个素数，同时也是一个回文数，编写程序，按要求寻找回文素数，每行显示 10 个回文素数。该程序提供重载方法 printPalinPrime：(1)要求找到指定数量 count 的回文素数，指定数量 count 作为方法参数；(2)要求寻找一个指定范围[m, n]之间的回文素数，以正整数 m、n 作为方法参数。方法 printPalinPrime 的返回值为 void，直接打印结果，修饰符也是 public static。在测试的 main 方法分别调用这两个重载的方法，比如，count =100，即找到并打印 100 个从 2 开始的回文素数；m=100，n=1000，寻找并打印[100,1000]之间的所有回文素数。', '参考代码：\npublic class Exercise4_17 {\n    public static void printPalinPrime(int count) {\n        int found = 0;\n        for (int num = 2; found < count; num++)\n            if (isPalinPrime(num))\n                System.out.printf("%-8d%s", num, ++found % 10 == 0 ? "\\n" : " ");\n    }\n    public static void printPalinPrime(int m, int n) {\n        int found = 0;\n        for (int num = m; num <= n; num++)\n            if (isPalinPrime(num))\n                System.out.printf("%-8d%s", num, ++found % 10 == 0 ? "\\n" : " ");\n    }\n    public static boolean isPalinPrime(int num) {\n        if (num < 2) return false;\n        for (int d = 2; d <= num / 2; d++) if (num % d == 0) return false;\n        String s = num + "";\n        for (int i = 0, j = s.length() - 1; i < j; i++, j--) if (s.charAt(i) != s.charAt(j)) return false;\n        return true;\n    }\n    public static void main(String[] args) { printPalinPrime(100); printPalinPrime(100, 1000); }\n}\nprintPalinPrime(int count) 与 printPalinPrime(int m, int n) 方法名相同、参数列表不同，构成重载；[100,1000] 区间内输出 101 131 151 181 191 313 353 373 383 727 / 757 787 797 919 929。', 2, '输出素数', 164, 57);
